import{_ as n,o as e,c as t,ag as o}from"./chunks/framework.PVHj0As1.js";const r="/pub-blog/assets/image-20251231014113706.BUeC93Bn.png",p="/pub-blog/assets/image-20251231014759156.DtdFcft8.png",s="/pub-blog/assets/image-20251231014812983.CjJ-5SDd.png",i="/pub-blog/assets/image-20251231015257274.CD4K0piS.png",l="/pub-blog/assets/image-20251231015504385.2UTMQuBC.png",m="/pub-blog/assets/image-20251231015518881.D-iB7PAU.png",c="/pub-blog/assets/image-20251231015617753.DFeBlxrm.png",d="/pub-blog/assets/image-20251231015654913.ekU2q6A_.png",f=JSON.parse('{"title":"HarmonyOS官方模板集成创新活动-流蓝卡片","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/我的上架应用-流蓝卡片/我的上架应用-流蓝卡片.md","filePath":"鸿蒙开发技巧/我的上架应用-流蓝卡片/我的上架应用-流蓝卡片.md","lastUpdated":1767117890000,"__rawMarkdown":"# HarmonyOS官方模板集成创新活动-流蓝卡片\\n\\n\\n\\n## 介绍\\n\\n​\\t**流蓝卡片**是一款适配了的鸿蒙6-API20的HarmonyOS应用，目的在于给用户提供方便、简单的方式创建好看的卡片，用于将卡片发布到各种社交平台上。\\n\\n![](assets/image-20251231014113706.png)\\n\\n## 实现过程\\n\\n​\\t目前是AI Codeing的时代，流蓝卡片其实也是基于AI Coding的产物，人工参与代码部分不超过5%。\\n\\n​\\t这款应用用到的亮点技术有：GLM4.6 + Gemini-3-pro + 智谱图片生成 + command line 构建鸿蒙工程。\\n\\n​\\t这套技术组成可以极大方便我开发鸿蒙应用。\\n\\n## 集成官方模板\\n\\n​\\t考虑到流蓝卡片目前是一个工具类型的应用，所以需要开发更多的一些相关工具，由于官方模板中提供了众多能力，这里就直接接入官方模板的-**通用工具模板**了。\\n\\n### 1. 寻找合适的官方模板\\n\\n在该网址中寻找你想要的官方模板，进行下载使用。\\n\\n> 官方模板地址：https://developer.huawei.com/consumer/cn/market/prod-list?origin=template&keyWord=%E5%8D%8E%E4%B8%BA%E6%A8%A1%E6%9D%BF&ha_source=9yhd&ha_sourceId=89000071\\n\\n![](assets/image-20251231014759156.png)\\n\\n---\\n\\n![](assets/image-20251231014812983.png)\\n\\n---\\n\\n\\n\\n### 2. 下载安装\\n\\n根据使用文档，点击集成\\n\\n![](assets/image-20251231015257274.png)\\n\\n\\n\\n### 3. 调整相关依赖\\n\\n​\\t根据自己当前工程需要，来调整引入的方式，如\\n\\n> **Entry**模块引入 Home模块，**Home**模块引入所有的工具模块\\n\\n![](assets/image-20251231015504385.png)\\n\\n---\\n\\n![](assets/image-20251231015518881.png)\\n\\n### 4. 开发调试以及发布上架\\n\\n​\\t由于工具中需要用到不少硬件资源，所以需要申请相关权限。\\n\\n![](assets/image-20251231015617753.png)\\n\\n这一部分权限需要在AGC平台上进行申请，接着跟着生成最新的调试和发布证书，否则开发调试和上架都会因为权限问题导致失败。\\n\\n![](assets/image-20251231015654913.png)\\n\\n## 流蓝卡片卡片的技术亮点\\n\\n   1. V2状态管理 - 全面采用@ObservedV2、@Trace、@ComponentV2等新一代状态管理技术\\n\\n   2. HAR模块化架构 - 30+独立HAR组件包，可独立开发、测试和发布\\n\\n   3. ZRouter路由方案 - 基于Navigation的声明式路由管理\\n\\n   4. 关系型数据库 - 完整的RdbManager + CardTable/InspirationTable/TemplateTable封装\\n\\n   5. 流畅动画 - 入场阶梯式动画，opacity + translate + delay实现平滑过渡\\n\\n   6. 浮动TabBar - 自定义底部导航栏，带浮动\\"+\\"按钮和阴影效果\\n\\n   7. @Extend组件扩展 - 提高代码复用性\\n\\n   8. AppStorage全局状态 - 跨页面状态共享\\n\\n   9. 多环境构建 - 调试/发布双环境配置\\n\\n10. 丰富工具生态 - 30+实用工具（计算、测量、创作、实用类）\\n\\n## 总结\\n\\n鸿蒙模板市场中提供了大量优质的三方组件和模板，提高了开发者开发同类功能的效率，点赞。\\n\\n\\n\\n如果你也想要了解HarmonyOS开发最新信息，欢迎技术交流\\n\\n> 我的博客： https://blog.zbztb.cn"}'),h={name:"鸿蒙开发技巧/我的上架应用-流蓝卡片/我的上架应用-流蓝卡片.md"};function g(_,a,b,u,q,k){return e(),t("div",null,[...a[0]||(a[0]=[o("",37)])])}const y=n(h,[["render",g]]);export{f as __pageData,y as default};
